begin;
alter table official_curriculum_catalog_status drop constraint if exists official_curriculum_catalog_status_status_check;
alter table official_curriculum_catalog_status add constraint official_curriculum_catalog_status_status_check check(status in ('FULL_PROGRAM','MODULAR_PARTIAL','PROTOCOL_ONLY','PROGRAM_PENDING','SUPERSEDED_BY_REGIONAL_PROGRAM'));
update official_curriculum_catalog_status set status='SUPERSEDED_BY_REGIONAL_PROGRAM',reason='2025-75 programı 2026-2027 itibarıyla kaldırıldı; 2026-91 Marmara ve 2026-92 Doğu Anadolu bölgesel programlarıyla değiştirildi.',source_url='https://meslek.meb.gov.tr/upload/krl/2026-91-MarmaraGastronomi.pdf',updated_at=now() where institution_type='MTAL' and field_name='Gastronomi ve Mutfak Sanatları' and branch_name in('Mutfak Sanatları','Pastacılık ve Ekmekçilik','Servis ve Kahve Hazırlama');
create temporary table _gb(subtype text,branch text,decision text,url text,pages jsonb,g10 jsonb,amp11 jsonb,atp11 jsonb,atp12 jsonb) on commit drop;
insert into _gb select * from jsonb_to_recordset('[{"subtype":"MARMARA_2026_91","branch":"Saray Mutfağı","decision":"2026-91","url":"https://meslek.meb.gov.tr/upload/krl/2026-91-MarmaraGastronomi.pdf","pages":{"AMP_STANDARD":22,"ATP_STANDARD":23,"AMP_ENTERPRISE_FROM_11":24},"g10":[["Türk Mutfağı Tarihi ve Uygulamaları",4],["Osmanlı Saray Mutfağı Kültürü ve Çok Katmanlı İstanbul",2],["Anadolu''da Tohumdan Tabağa",2],["Marmara Yöresel Lezzetleri",5]],"amp11":[["Anadolu''da Sürü, Süt ve Sular",2],["Osmanlı Saray Mutfağı Yemekleri",7],["Osmanlı Saray Mutfağında Helvacılık, Şekerleme ve Reçel Teknikleri",4],["Uluslararası Mutfaklar",4]],"atp11":[["Anadolu''da Sürü, Süt ve Sular",2],["Osmanlı Saray Mutfağı Yemekleri",7]],"atp12":[["Osmanlı Saray Mutfağında Helvacılık, Şekerleme ve Reçel Teknikleri",4],["Uluslararası Mutfaklar",4]]},{"subtype":"MARMARA_2026_91","branch":"Helvacılık, Şerbet ve Tatlı Sanatları","decision":"2026-91","url":"https://meslek.meb.gov.tr/upload/krl/2026-91-MarmaraGastronomi.pdf","pages":{"AMP_STANDARD":25,"ATP_STANDARD":26,"AMP_ENTERPRISE_FROM_11":27},"g10":[["Türk Mutfağı Tarihi ve Uygulamaları",4],["Anadolu''da Sürü, Süt ve Sular",2],["Anadolu''da Tohumdan Tabağa",2],["Osmanlı Saray Mutfağında Tatlılar ve Şerbetler",5]],"amp11":[["Osmanlı Saray Mutfağında Ekmekçilik ve Fırın Kültürü",4],["Osmanlı Saray Mutfağında Helvacılık, Şekerleme ve Reçel Teknikleri",4],["Marmara Yöresel Lezzetleri",5],["Uluslararası Mutfaklar",4]],"atp11":[["Marmara Yöresel Lezzetleri",5],["Osmanlı Saray Mutfağında Helvacılık, Şekerleme ve Reçel Teknikleri",4]],"atp12":[["Osmanlı Saray Mutfağında Ekmekçilik ve Fırın Kültürü",4],["Uluslararası Mutfaklar",4]]},{"subtype":"MARMARA_2026_91","branch":"Misafir Deneyimi ve Servis Yönetimi","decision":"2026-91","url":"https://meslek.meb.gov.tr/upload/krl/2026-91-MarmaraGastronomi.pdf","pages":{"AMP_STANDARD":28,"ATP_STANDARD":29,"AMP_ENTERPRISE_FROM_11":30},"g10":[["Anadolu''da Tohumdan Tabağa",2],["Servis Teknikleri",4],["Restoran Hizmetleri",2],["Marmara Yöresel Lezzetleri",5]],"amp11":[["Anadolu''da Sürü, Süt ve Sular",2],["Türk Mutfağı Tarihi ve Uygulamaları",4],["Türk Mutfağında Servis Yöntemleri",4],["Kahve Teknikleri",3],["Çay Demleme Teknikleri",2],["Anadolu''da İçecekler",2]],"atp11":[["Anadolu''da Sürü, Süt ve Sular",2],["Kahve Teknikleri",3],["Çay Demleme Teknikleri",2],["Anadolu''da İçecekler",2]],"atp12":[["Türk Mutfağı Tarihi ve Uygulamaları",4],["Türk Mutfağında Servis Yöntemleri",4]]},{"subtype":"DOGU_ANADOLU_2026_92","branch":"Süt ve Süt Ürünleri","decision":"2026-92","url":"https://meslek.meb.gov.tr/upload/krl/2026-92-DoguAnadoluGastronomi.pdf","pages":{"AMP_STANDARD":21,"ATP_STANDARD":22,"AMP_ENTERPRISE_FROM_11":23},"g10":[["Anadolu''da Sürü, Süt ve Sular",2],["Yayla Kültürü ve Süt Ürünleri",6],["Doğu Anadolu Yöresel Lezzetleri",5]],"amp11":[["Türk Mutfağı Tarihi ve Uygulamaları",4],["Doğu Anadolu Mutfağı Süt ve Süt Ürünleri Yemekleri",5],["Uluslararası Mutfaklar",4],["Anadolu''da Tohumdan Tabağa",2],["Tadım Teknikleri",2]],"atp11":[["Türk Mutfağı Tarihi ve Uygulamaları",4],["Doğu Anadolu Mutfağı Süt ve Süt Ürünleri Yemekleri",5]],"atp12":[["Uluslararası Mutfaklar",4],["Anadolu''da Tohumdan Tabağa",2],["Tadım Teknikleri",2]]},{"subtype":"DOGU_ANADOLU_2026_92","branch":"Et ve Et Ürünleri","decision":"2026-92","url":"https://meslek.meb.gov.tr/upload/krl/2026-92-DoguAnadoluGastronomi.pdf","pages":{"AMP_STANDARD":24,"ATP_STANDARD":25,"AMP_ENTERPRISE_FROM_11":26},"g10":[["Anadolu''da Sürü, Süt ve Sular",2],["Doğu Anadolu Mutfağında Et Pişirme Teknikleri",6],["Doğu Anadolu Yöresel Lezzetleri",5]],"amp11":[["Türk Mutfağı Tarihi ve Uygulamaları",4],["Uluslararası Mutfaklar",4],["Anadolu''da Tohumdan Tabağa",2],["Tadım Teknikleri",2],["Doğu Anadolu Mutfağı Et Yemekleri",5]],"atp11":[["Türk Mutfağı Tarihi ve Uygulamaları",4],["Doğu Anadolu Mutfağı Et Yemekleri",5]],"atp12":[["Uluslararası Mutfaklar",4],["Anadolu''da Tohumdan Tabağa",2],["Tadım Teknikleri",2]]},{"subtype":"DOGU_ANADOLU_2026_92","branch":"Misafir Deneyimi ve Servis Yönetimi","decision":"2026-92","url":"https://meslek.meb.gov.tr/upload/krl/2026-92-DoguAnadoluGastronomi.pdf","pages":{"AMP_STANDARD":27,"ATP_STANDARD":28,"AMP_ENTERPRISE_FROM_11":29},"g10":[["Anadolu''da Sürü, Süt ve Sular",2],["Servis Teknikleri",4],["Restoran Hizmetleri",2],["Doğu Anadolu Yöresel Lezzetleri",5]],"amp11":[["Türk Mutfağı Tarihi ve Uygulamaları",4],["Türk Mutfağında Servis Yöntemleri",4],["Kahve Teknikleri",3],["Çay Demleme Teknikleri",2],["Anadolu''da İçecekler",2],["Anadolu''da Tohumdan Tabağa",2]],"atp11":[["Kahve Teknikleri",3],["Çay Demleme Teknikleri",2],["Anadolu''da İçecekler",2],["Anadolu''da Tohumdan Tabağa",2]],"atp12":[["Türk Mutfağı Tarihi ve Uygulamaları",4],["Türk Mutfağında Servis Yöntemleri",4]]}]'::jsonb) as x(subtype text,branch text,decision text,url text,pages jsonb,g10 jsonb,amp11 jsonb,atp11 jsonb,atp12 jsonb);
create temporary table _gc as select b.*,v.program,v.variant,(b.pages->>v.pk)::smallint page from _gb b cross join(values('AMP','STANDARD','AMP_STANDARD'),('ATP','STANDARD','ATP_STANDARD'),('AMP','ENTERPRISE_FROM_11','AMP_ENTERPRISE_FROM_11'))v(program,variant,pk);
with g(grade)as(values(9::smallint),(10::smallint),(11::smallint),(12::smallint)),x as(select c.*,g.grade,case when c.program='AMP' and c.variant='STANDARD' then case g.grade when 9 then 41 when 10 then 41 when 11 then 33 else 35 end when c.program='ATP' then case g.grade when 9 then 41 when 10 then 41 when 11 then 25 else 19 end else case g.grade when 9 then 41 when 10 then 41 when 11 then 41 else 42 end end::smallint required,case when c.program='AMP' and c.variant='STANDARD' then case g.grade when 11 then 12 when 12 then 9 else 4 end when c.program='ATP' then case g.grade when 11 then 20 when 12 then 23 else 4 end else 4 end::smallint elective,case when c.program='ATP' and g.grade=12 then 3 else 0 end::smallint elective_voc,case when c.program='AMP' and c.variant='STANDARD' and g.grade=12 then 44 when c.variant='ENTERPRISE_FROM_11' and g.grade=12 then 46 else 45 end::smallint target,case g.grade when 9 then 28 when 10 then 27 when 11 then 15 else 10 end::smallint common_h,case when g.grade=9 then 12 when g.grade=10 then 13 when c.program='AMP' and c.variant='STANDARD' and g.grade=11 then 17 when c.program='AMP' and c.variant='STANDARD' and g.grade=12 then 24 when c.program='ATP' and g.grade=11 then 9 when c.program='ATP' and g.grade=12 then 8 when c.variant='ENTERPRISE_FROM_11' and g.grade=11 then 25 else 32 end::smallint voc_h,case when c.program='AMP' and c.variant='STANDARD' and g.grade=12 then 24 when c.variant='ENTERPRISE_FROM_11' and g.grade=11 then 16 when c.variant='ENTERPRISE_FROM_11' and g.grade=12 then 24 else 0 end::smallint enterprise_h,case when c.variant='ENTERPRISE_FROM_11' and g.grade=12 then 0 else 1 end::smallint guidance_h from _gc c cross join g)
insert into official_curriculum_profiles(effective_academic_year,school_type,school_subtype,program_type,field_name,branch_name,grade_level,required_course_count,required_hour_total,elective_course_min,elective_course_max,elective_hour_min,elective_hour_max,total_hour_min,total_hour_max,total_hour_target,group_rules,source_file_name,source_decision_no,source_note,active,schedule_variant,common_hours,vocational_hours,elective_vocational_hours,elective_hours,guidance_hours,enterprise_hours,applicability_status,source_page,parsed_constraints,academic_support_hours) select '2026-2027','MTAL',subtype,program,'Gastronomi ve Mutfak Sanatları',branch,grade,0,required,0,null,elective,elective,target,target,target,'[]',url,decision,decision||' bölgesel Gastronomi programı; 2025-75 kaldırıldı.',true,variant,common_h,voc_h,elective_voc,elective,guidance_h,enterprise_h,'ACTIVE',page,jsonb_build_object('region',subtype,'decision',decision,'supersedes','2025-75','enterpriseFromGrade11Conditional',variant='ENTERPRISE_FROM_11'),0 from x where not exists(select 1 from official_curriculum_profiles p where p.effective_academic_year='2026-2027' and p.school_type='MTAL' and coalesce(p.school_subtype,'')=subtype and coalesce(p.program_type,'')=program and p.field_name='Gastronomi ve Mutfak Sanatları' and p.branch_name=branch and p.grade_level=grade and coalesce(p.schedule_variant,'STANDARD')=variant);
create temporary table _gcommon(grade smallint,name text,h smallint) on commit drop;
insert into _gcommon values (9,'Türk Dili ve Edebiyatı',5),(9,'Din Kültürü ve Ahlak Bilgisi',2),(9,'Tarih',2),(9,'Coğrafya',2),(9,'Matematik',5),(9,'Fizik',2),(9,'Kimya',2),(9,'Biyoloji',2),(9,'Yabancı Dil',4),(9,'Beden Eğitimi ve Spor/Görsel Sanatlar/Müzik',2),(10,'Türk Dili ve Edebiyatı',4),(10,'Din Kültürü ve Ahlak Bilgisi',2),(10,'Tarih',2),(10,'Coğrafya',2),(10,'Matematik',5),(10,'Fizik',2),(10,'Kimya',2),(10,'Biyoloji',2),(10,'Felsefe',2),(10,'Yabancı Dil',2),(10,'Beden Eğitimi ve Spor/Görsel Sanatlar/Müzik',2),(11,'Türk Dili ve Edebiyatı',4),(11,'Din Kültürü ve Ahlak Bilgisi',2),(11,'Tarih',2),(11,'Felsefe',2),(11,'Yabancı Dil',2),(11,'Beden Eğitimi ve Spor/Görsel Sanatlar/Müzik',2),(11,'Sağlık Bilgisi ve Trafik Kültürü',1),(12,'Türk Dili ve Edebiyatı',4),(12,'Din Kültürü ve Ahlak Bilgisi',2),(12,'T.C. İnkılap Tarihi ve Atatürkçülük',2),(12,'Yabancı Dil',2);
insert into course_catalog(name,category) select distinct name,'zorunlu' from _gcommon g where not exists(select 1 from course_catalog c where c.name=g.name);
insert into course_catalog(name,category) select 'Rehberlik ve Yönlendirme','rehberlik' where not exists(select 1 from course_catalog where name='Rehberlik ve Yönlendirme');
insert into official_course_schedule_catalog(effective_academic_year,school_type,program_type,grade_level,course_id,category,hour_options,max_selections,repeat_across_years,source_file_name,source_note,active,field_name,branch_name,school_subtype,source_decision_no,source_decision_date,source_page,source_section,parser_confidence,needs_review,schedule_variant,parsed_constraints) select '2026-2027','MTAL',c.program,g.grade,cc.id,'zorunlu',array[g.h]::smallint[],1,false,c.url,c.decision||' bölgesel Gastronomi haftalık ders çizelgesi',true,'Gastronomi ve Mutfak Sanatları',c.branch,c.subtype,c.decision,date'2026-08-07',c.page,'9.5 HAFTALIK DERS ÇİZELGESİ',1,false,c.variant,jsonb_build_object('region',c.subtype,'tablePage',c.page) from _gc c cross join _gcommon g join course_catalog cc on cc.name=g.name where not exists(select 1 from official_course_schedule_catalog s where s.active and s.effective_academic_year='2026-2027' and s.school_type='MTAL' and coalesce(s.school_subtype,'')=c.subtype and coalesce(s.program_type,'')=c.program and s.field_name='Gastronomi ve Mutfak Sanatları' and s.branch_name=c.branch and s.grade_level=g.grade and coalesce(s.schedule_variant,'STANDARD')=c.variant and s.course_id=cc.id);
insert into official_course_schedule_catalog(effective_academic_year,school_type,program_type,grade_level,course_id,category,hour_options,max_selections,repeat_across_years,source_file_name,source_note,active,field_name,branch_name,school_subtype,source_decision_no,source_decision_date,source_page,source_section,parser_confidence,needs_review,schedule_variant,parsed_constraints) select '2026-2027','MTAL',c.program,g.grade,cc.id,'rehberlik',array[1]::smallint[],1,true,c.url,c.decision||' bölgesel Gastronomi haftalık ders çizelgesi',true,'Gastronomi ve Mutfak Sanatları',c.branch,c.subtype,c.decision,date'2026-08-07',c.page,'9.5 HAFTALIK DERS ÇİZELGESİ',1,false,c.variant,jsonb_build_object('region',c.subtype,'tablePage',c.page) from _gc c cross join(values(9::smallint),(10::smallint),(11::smallint),(12::smallint))g(grade) join course_catalog cc on cc.name='Rehberlik ve Yönlendirme' where not(c.variant='ENTERPRISE_FROM_11' and g.grade=12) and not exists(select 1 from official_course_schedule_catalog s where s.active and s.effective_academic_year='2026-2027' and s.school_type='MTAL' and coalesce(s.school_subtype,'')=c.subtype and coalesce(s.program_type,'')=c.program and s.field_name='Gastronomi ve Mutfak Sanatları' and s.branch_name=c.branch and s.grade_level=g.grade and coalesce(s.schedule_variant,'STANDARD')=c.variant and s.course_id=cc.id);
create temporary table _gv as with base as(select c.*,jsonb_build_array(jsonb_build_array('Mesleki Gelişim Atölyesi',2),jsonb_build_array('Temel Gastronomi Uygulamaları',6),jsonb_build_array('Mutfakta İş Sağlığı ve Gıda Güvenliği',2),jsonb_build_array('Beslenme İlkeleri ve Menü Planlama',2))g9 from _gc c),rows as(select b.*,9::smallint grade,b.g9 arr from base b union all select b.*,10,b.g10 from base b union all select b.*,11,case when program='AMP' and variant='STANDARD' then amp11 when program='ATP' then atp11 else atp11||jsonb_build_array(jsonb_build_array('İşletmelerde Mesleki Eğitim',16)) end from base b union all select b.*,12,case when program='AMP' and variant='STANDARD' then jsonb_build_array(jsonb_build_array('İşletmelerde Mesleki Eğitim',24)) when program='ATP' then atp12 else atp12||jsonb_build_array(jsonb_build_array('İşletmelerde Mesleki Eğitim',24)) end from base b) select subtype,branch,program,variant,grade,e->>0 name,(e->>1)::smallint h,page,decision,url from rows cross join lateral jsonb_array_elements(arr)e;
insert into course_catalog(name,category) select distinct name,'uygulama' from _gv v where not exists(select 1 from course_catalog c where c.name=v.name);
insert into official_course_schedule_catalog(effective_academic_year,school_type,program_type,grade_level,course_id,category,hour_options,max_selections,repeat_across_years,source_file_name,source_note,active,field_name,branch_name,school_subtype,source_decision_no,source_decision_date,source_page,source_section,parser_confidence,needs_review,schedule_variant,parsed_constraints) select '2026-2027','MTAL',v.program,v.grade,c.id,'uygulama',array[v.h]::smallint[],1,false,v.url,v.decision||' bölgesel Gastronomi meslek dersi',true,'Gastronomi ve Mutfak Sanatları',v.branch,v.subtype,v.decision,date'2026-08-07',v.page,'9.5 HAFTALIK DERS ÇİZELGESİ',1,false,v.variant,jsonb_build_object('region',v.subtype,'tablePage',v.page,'enterprise',v.name='İşletmelerde Mesleki Eğitim') from _gv v join course_catalog c on c.name=v.name where not exists(select 1 from official_course_schedule_catalog s where s.active and s.effective_academic_year='2026-2027' and s.school_type='MTAL' and coalesce(s.school_subtype,'')=v.subtype and coalesce(s.program_type,'')=v.program and s.field_name='Gastronomi ve Mutfak Sanatları' and s.branch_name=v.branch and s.grade_level=v.grade and coalesce(s.schedule_variant,'STANDARD')=v.variant and s.course_id=c.id);
update official_curriculum_profiles p set required_course_count=q.n,updated_at=now() from(select school_subtype,program_type,branch_name,grade_level,schedule_variant,count(*)::smallint n from official_course_schedule_catalog where active and effective_academic_year='2026-2027' and school_type='MTAL' and field_name='Gastronomi ve Mutfak Sanatları' and school_subtype in('MARMARA_2026_91','DOGU_ANADOLU_2026_92') group by 1,2,3,4,5)q where p.active and p.effective_academic_year='2026-2027' and p.school_type='MTAL' and p.field_name='Gastronomi ve Mutfak Sanatları' and p.school_subtype=q.school_subtype and p.program_type=q.program_type and p.branch_name=q.branch_name and p.grade_level=q.grade_level and p.schedule_variant=q.schedule_variant;
create or replace function public.audit_mtal_curriculum_v1() returns table(severity text,code text,field_name text,branch_name text,grade_level smallint,program_type text,schedule_variant text,detail text) language sql stable security definer set search_path to'public' as $f$ with p as(select coalesce(school_subtype,'') school_subtype,field_name,coalesce(branch_name,'') branch_name,grade_level,program_type,coalesce(schedule_variant,'STANDARD') schedule_variant,required_hour_total,coalesce(elective_hours,0) elective_hours,coalesce(elective_vocational_hours,0) elective_vocational_hours,coalesce(academic_support_hours,0) academic_support_hours,total_hour_target,source_file_name,source_decision_no from official_curriculum_profiles where school_type='MTAL' and active),r as(select coalesce(school_subtype,'') school_subtype,field_name,coalesce(branch_name,'') branch_name,grade_level,program_type,coalesce(schedule_variant,'STANDARD') schedule_variant,count(*) row_count,coalesce(sum((hour_options)[1]),0)::int fixed_hours from official_course_schedule_catalog where school_type='MTAL' and active group by 1,2,3,4,5,6),f(severity,code,field_name,branch_name,grade_level,program_type,schedule_variant,detail)as(select'ERROR','PROFILE_WITHOUT_ROWS',p.field_name,p.branch_name,p.grade_level,p.program_type,p.schedule_variant,'profile exists but no active course rows; subtype='||p.school_subtype from p left join r using(school_subtype,field_name,branch_name,grade_level,program_type,schedule_variant) where coalesce(r.row_count,0)=0 union all select'ERROR','FIXED_HOURS_MISMATCH',p.field_name,p.branch_name,p.grade_level,p.program_type,p.schedule_variant,format('subtype=%s profile required=%s rows=%s',p.school_subtype,p.required_hour_total,r.fixed_hours) from p join r using(school_subtype,field_name,branch_name,grade_level,program_type,schedule_variant) where r.fixed_hours<>p.required_hour_total union all select'ERROR','TOTAL_HOURS_MISMATCH',p.field_name,p.branch_name,p.grade_level,p.program_type,p.schedule_variant,format('subtype=%s target=%s computed=%s',p.school_subtype,p.total_hour_target,p.required_hour_total+p.elective_hours+p.elective_vocational_hours+p.academic_support_hours) from p where p.total_hour_target is not null and p.required_hour_total+p.elective_hours+p.elective_vocational_hours+p.academic_support_hours<>p.total_hour_target union all select'ERROR','MISSING_SOURCE',p.field_name,p.branch_name,p.grade_level,p.program_type,p.schedule_variant,'missing source; subtype='||p.school_subtype from p where coalesce(source_file_name,'')='' or coalesce(source_decision_no,'')='' union all select'WARNING','SOURCE_NOT_PDF',p.field_name,p.branch_name,p.grade_level,p.program_type,p.schedule_variant,source_file_name||'; subtype='||p.school_subtype from p where coalesce(source_file_name,'')<>'' and source_file_name not ilike'%.pdf%') select * from f order by severity desc,field_name,branch_name,grade_level,program_type,schedule_variant,code;$f$;
commit;